from collections import deque

def solve(grid, start, goal):
    # Helper to get neighbors of a position
    def neighbors(r, c):
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]) and grid[nr][nc] == '.':
                yield nr, nc

    # Check if start or goal is a wall
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    # If start == goal, return [start] if it's a free cell
    if start == goal and grid[start[0]][start[1]] == '.':
        return [start]

    # Initialize both BFS queues and parent dicts
    q_start = deque([start])
    q_goal = deque([goal])
    parents_start = {start: None}
    parents_goal = {goal: None}

    # Alternate BFS expansion (start -> goal -> start -> goal ...)
    while q_start and q_goal:
        # Expand from start side
        if q_start:
            for _ in range(len(q_start)):
                r, c = q_start.popleft()
                for nr, nc in neighbors(r, c):
                    if (nr, nc) not in parents_start:
                        parents_start[(nr, nc)] = (r, c)
                        q_start.append((nr, nc))
                        # Check if this new node has been visited by the goal side
                        if (nr, nc) in parents_goal:
                            return reconstruct_path(parents_start, parents_goal, (nr, nc), start, goal)

        # Expand from goal side
        if q_goal:
            for _ in range(len(q_goal)):
                r, c = q_goal.popleft()
                for nr, nc in neighbors(r, c):
                    if (nr, nc) not in parents_goal:
                        parents_goal[(nr, nc)] = (r, c)
                        q_goal.append((nr, nc))
                        # Check if this new node has been visited by the start side
                        if (nr, nc) in parents_start:
                            return reconstruct_path(parents_start, parents_goal, (nr, nc), start, goal)

    return []

def reconstruct_path(ps, pg, meet, start, goal):
    # Get path from start to meeting point
    path_start = []
    node = meet
    while node != start:
        path_start.append(node)
        node = ps[node]
    path_start.reverse()

    # Get path from meeting point to goal
    path_goal = []
    node = meet
    while node != goal:
        node = pg[node]
        path_goal.append(node)

    # Combine and return
    return [start] + path_start + path_goal

