    def heur(pos):
        """Manhattan distance from current cell to goal. Used to guide the search."""
        return abs(pos[0] - goal[0]) + abs(pos[1] - goal[1])

    frontier = [(heur(start), 0, start)]  # (f_score, g_score, cell)
    best_cost = {start: 0}
    predecessors = {start: None}
    final_set = set()

    while frontier:
        _, current_cost, current = heapq.heappop(frontier)
        if current in final_set:
            continue
        if current == goal:
            # Reconstruct the path from goal back to start
            reconstructed = []
            while current is not None:
                reconstructed.append(current)
                current = predecessors[current]
            reconstructed.reverse()

            expanded_path = [reconstructed[0]]
            for i in range(len(reconstructed) - 1):
                path_x, path_y = reconstructed[i]
                dest_x, dest_y = reconstructed[i + 1]
                # Fill in intermediate steps between each node in the path
                while (path_x, path_y) != (dest_x, dest_y):
                    path_x += 1 if dest_x > path_x else -1 if dest_x < path_x else 0
                    path_y += 1 if dest_y > path_y else -1 if dest_y < path_y else 0
                    expanded_path.append((path_x, path_y))
            return expanded_path

        final_set.add(current)
        x, y = current
        # Identify jump points in each of four directions and expand them
        neighbors = [horizontal_identify(x, y, 1), horizontal_identify(x, y, -1),
                     vertical_identify(x, y, 1), vertical_identify(x, y, -1)]

        for neighbor in neighbors:
            if neighbor is not None and neighbor not in final_set:
                new_cost = current_cost + abs(neighbor[0] - x) + abs(neighbor[1] - y)
                if new_cost < best_cost.get(neighbor, float('inf')):
                    best_cost[neighbor] = new_cost
                    predecessors[neighbor] = current
                    heapq.heappush(frontier, (new_cost + heur(neighbor), new_cost, neighbor))
    return []
